WITH exploded AS (SELECT id, host, log_ts, latency_ms, status_code, key, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS key, v) SELECT CASE WHEN status_code >= 394 THEN 'PREMIUM' ELSE 'STANDARD' END AS status_code_tier, key, CORR(status_code, latency_ms) AS corr_status_code_latency_ms, PERCENTILE_APPROX(status_code, 0.9) AS status_code_p90, BIT_AND(latency_ms) AS latency_ms_bit_and, RANK() OVER (PARTITION BY CASE WHEN status_code >= 394 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY PERCENTILE_APPROX(status_code, 0.9) DESC) AS status_code_p90_rank FROM exploded GROUP BY 1, 2 ORDER BY key DESC NULLS LAST;
